"""
Paper 59 certificate, part O: the size of the prize for oscillator ports (the gear-charge ergotropy).
mpmath / fractions only.  Usage: python p59_cert.py

CLAIM (derived analytically 2026-10-02 before any numerics).  Two harmonic modes A, B (frequencies w_A, w_B) in thermal
states with u = e^{-beta_A w_A}, v = e^{-beta_B w_B}.  For coprime (k, m), let U_{k,m} be the unitaries that conserve the
"gear charge" K = k N_A + m N_B -- exactly the dynamics generated by a^{dag m} b^k + h.c. together with N_A, N_B (each K-block
is one ladder (a + jm, b - jk)).  Then the maximal work extractable by U_{k,m} is
    W_{k,m} = max{ 0, (k w_B - m w_A) [ nbar(beta_B k w_B) - nbar(beta_A m w_A) ] },     nbar(z) = 1/(e^z - 1),
the energy of the composite exchange times the difference of Bose occupations of the composite quanta.  W > 0 iff k/m lies
strictly inside the Carnot window between w_A/w_B and (beta_A w_A)/(beta_B w_B).  Near equilibrium (beta_A = beta(1+delta),
beta_B = beta, k/m = x(1 + theta delta), x = w_A/w_B):
    W_{k,m} = T delta^2 theta(1 - theta) C_E(m beta w_A) (1 + O(delta)),   C_E(z) = z^2 e^z/(e^z - 1)^2 (Einstein),
and the reversible (finite-body Carnot) work between the two modes is W_rev = (T/2) delta^2 C_A C_B/(C_A + C_B)(1 + O(delta)).

PRE-REGISTERED FALSIFIERS (written 2026-10-02 before the first run)
  O1 [exact, 40 digits] for 24 random parameter sets (rational u, v in [1/5, 7/10], rational w_A < w_B, coprime k, m <= 7,
     both orientations included), the brute-force K-block ergotropy (every ladder sorted: populations descending against
     energies ascending; Fock cutoffs with geometric tail < 1e-30) equals the closed form to relative 1e-25 when positive,
     and is zero (< 1e-30) when the closed form is <= 0.                          L: any mismatch.
  O2 [exact] for 300 random windows (x in (0.2, 0.95), delta in (0.005, 0.5)), the least order k + m with W_{k,m} > 0
     (search over coprime k, m <= 400) is attained by the Stern-Brocot simplest fraction of the window, which also has
     the least k and the least m.                                                 L: any counterexample.
  O3 [numerics] near-equilibrium formula: for fixed fractions (2/3 near x = 1/phi; 3/5 near x = 1/sqrt3; 7/11 near
     x = 0.62) with theta = 1/2 and beta w_A in {0.01, 1}, the relative error of the formula at delta = 1e-2, 1e-3, 1e-4
     shrinks by a factor >= 5 per decade.                                         L: otherwise.
  O4 [numerics] classical optimality: with theta = 1/2 and m beta w_A = 1e-3, W_{k,m}/W_rev is within 2% of 1 at
     delta = 1e-3 (one well-placed k:m exchange captures the reversible work to leading order).   L: otherwise.
  O5 [exact bound + numerics] resonance penalty in the prize: for x = 1/2 the minimal-order exchange has
     4 theta (1 - theta) < 8 delta (exact, from m = least odd integer > 1/delta), so in the classical regime
     W_min/W_rev < 8 delta (1 + O(delta)); checked at delta = 1e-2, 1e-3; for x = 1/phi the mean of 4 theta(1 - theta)
     over 200 log-uniform delta in [1e-4, 1e-2] exceeds 0.3.                     L: otherwise.

RUN LOG
  Run 1 (2026-10-02, p59_run1.log): O2, O3, O4 PASS (blind).  O1 FAILED on a CHECKER ARTIFACT: the truncation bound
  "a missing ladder needs a > NA/2 or b > NB/2" is wrong when k != m (it needs a > Kmax/2k or b > Kmax/2m, which for
  K_max = min(k NA, m NB) can be far below NB/2), so ladders at the 1e-19 level were cut; the two failing cases (k, m) =
  (2, 7), (6, 7) agree with the closed form to 12 printed digits.  O5 gave NO VERDICT: the checker's mp.findroot for the
  reversible-work temperature stepped outside the physical range (complex log, overflow) at beta = 1e-6.  Both retained.
  Fix: choose K* so that P(a > K*/2k) and P(b > K*/2m) are both < 1e-34 and set NA = K*/k, NB = K*/m; solve for beta*
  by bisection on [min, max] of the two inverse temperatures.  Run 2 is NOT BLIND for O1 and O5.
"""
import math, random
from fractions import Fraction as Fr
import mpmath as mp

mp.mp.dps = 40
res = []
def check(name, ok, detail=""):
    res.append(bool(ok))
    print(f"[{'PASS' if ok else 'FAIL'}] {name}  {detail}", flush=True)

def nbar(z):
    return 1 / mp.expm1(z)

def closed_form(u, v, wA, wB, k, m):
    bAwA = -mp.log(u); bBwB = -mp.log(v)
    Delta = k * wB - m * wA
    val = Delta * (nbar(k * bBwB) - nbar(m * bAwA))
    return max(mp.mpf(0), val), val

def brute(u, v, wA, wB, k, m, tail=mp.mpf('1e-66')):
    # cutoffs: P(N_A > NA) = u^(NA+1) < tail, same for B; ladders with K <= Kmax fully inside.  A missing ladder needs
    # a > NA/2 or b > NB/2 (since K > min(k NA, m NB)), so the neglected probability is < 2 sqrt(tail) ~ 1e-33.
    # run 2: K* with P(a > K*/2k) < 1e-34 and P(b > K*/2m) < 1e-34; every state with k a + m b <= K* is enumerated
    Ka = 2 * k * (int(mp.ceil(mp.log(mp.mpf('1e-34')) / mp.log(u))) + 1)
    Kb = 2 * m * (int(mp.ceil(mp.log(mp.mpf('1e-34')) / mp.log(v))) + 1)
    Kmax = max(Ka, Kb)
    NA = Kmax // k + 1; NB = Kmax // m + 1
    W = mp.mpf(0)
    for K in range(Kmax + 1):
        states = []
        for a in range(0, K // k + 1):
            rem = K - k * a
            if rem % m == 0:
                b = rem // m
                p = (1 - u) * u ** a * (1 - v) * v ** b
                E = a * wA + b * wB
                states.append((p, E))
        if len(states) < 2:
            continue
        ps = sorted((s[0] for s in states), reverse=True)
        Es = sorted(s[1] for s in states)
        W += mp.fsum(p * E for p, E in states) - mp.fsum(p * E for p, E in zip(ps, Es))
    return W

rng = random.Random(590001)
def rfr(lo, hi, den=60):
    return Fr(rng.randint(int(lo * den), int(hi * den)), den)

ok1 = True; d1 = []; npos = 0
for t in range(24):
    u = rfr(0.2, 0.7); v = rfr(0.2, 0.7)
    wA = rfr(0.3, 1.0); wB = wA + rfr(0.05, 1.5)
    while True:
        k = rng.randint(1, 7); m = rng.randint(1, 7)
        if math.gcd(k, m) == 1:
            break
    um, vm = mp.mpf(u.numerator) / u.denominator, mp.mpf(v.numerator) / v.denominator
    wAm, wBm = mp.mpf(wA.numerator) / wA.denominator, mp.mpf(wB.numerator) / wB.denominator
    cf, raw = closed_form(um, vm, wAm, wBm, k, m)
    bf = brute(um, vm, wAm, wBm, k, m)
    if cf > 0:
        npos += 1
        good = abs(bf / cf - 1) < mp.mpf('1e-25')
    else:
        good = abs(bf) < mp.mpf('1e-30')
    ok1 &= good
    if not good:
        d1.append(f"t={t} k={k} m={m} cf={mp.nstr(cf, 12)} bf={mp.nstr(bf, 12)}")
check("O1 [exact, 40 digits] gear-charge ergotropy = closed form (24 random sets)", ok1,
      ("; ".join(d1) if d1 else f"all agree ({npos} positive, {24 - npos} zero)"))

def simplest(lo, hi):
    """Stern-Brocot simplest fraction strictly inside (lo, hi), lo < hi positive Fractions."""
    lp, lq, rp, rq = 0, 1, 1, 0
    while True:
        mp_, mq = lp + rp, lq + rq
        f = Fr(mp_, mq)
        if f <= lo:
            lp, lq = mp_, mq
        elif f >= hi:
            rp, rq = mp_, mq
        else:
            return mp_, mq

ok2 = True; d2 = []
for t in range(300):
    x = Fr(rng.randint(200, 950), 1000)
    dl = Fr(rng.randint(5, 500), 1000)
    lo, hi = x, x * (1 + dl)
    best = None; bestk = None; bestm = None
    for mm in range(1, 401):
        kk = (lo * mm).__floor__() + 1          # least k with k/m > lo (non-coprime k/m reduce to a smaller order)
        if kk <= 400 and Fr(kk, mm) < hi:
            if best is None or kk + mm < best:
                best = kk + mm
            if bestk is None or kk < bestk:
                bestk = kk
            if bestm is None:
                bestm = mm
    p, q = simplest(lo, hi)
    if not (best == p + q and bestk == p and bestm == q):
        ok2 = False; d2.append(f"x={x} delta={dl}: simplest {p}/{q}, best order {best}, k {bestk}, m {bestm}")
check("O2 [exact] least order k+m with W>0 = Stern-Brocot simplest fraction (also least k and least m), 300 windows",
      ok2, "; ".join(d2[:3]) if d2 else "all 300 agree")

def C_E(z):
    return z ** 2 * mp.exp(z) / mp.expm1(z) ** 2

def near_eq_case(xv, k, m, delta, bwA, theta_target=mp.mpf('0.5')):
    """choose w_A = 1, w_B = 1/x with x tuned so that k/m = x(1 + theta delta); beta = bwA (beta w_A)."""
    delta = mp.mpf(delta)
    x = mp.mpf(k) / m / (1 + theta_target * delta)
    wA = mp.mpf(1); wB = wA / x
    beta = mp.mpf(bwA)
    bA = beta * (1 + delta); bB = beta
    u = mp.exp(-bA * wA); v = mp.exp(-bB * wB)
    W, _ = closed_form(u, v, wA, wB, k, m)
    T = 1 / beta
    pred = T * delta ** 2 * theta_target * (1 - theta_target) * C_E(m * beta * wA)
    return W, pred, (u, v, wA, wB, bA, bB)

ok3 = True; d3 = []
for (xv, k, m) in [(None, 2, 3), (None, 3, 5), (None, 7, 11)]:
    for bwA in ('0.01', '1'):
        errs = []
        for dl in ('1e-2', '1e-3', '1e-4'):
            W, pred, _ = near_eq_case(xv, k, m, dl, bwA)
            errs.append(abs(W / pred - 1))
        shrink = all(errs[i] / errs[i + 1] >= 5 for i in range(2))
        ok3 &= shrink
        d3.append(f"{k}/{m} bw={bwA}: rel err {[mp.nstr(e, 3) for e in errs]}")
check("O3 [numerics] near-equilibrium formula T delta^2 theta(1-theta) C_E(m beta w_A): error shrinks >= 5x per decade",
      ok3, "; ".join(d3))

def W_rev(wA, wB, bA, bB):
    """reversible work between two finite oscillators: equalize entropy at a common beta*, W = E_i - E_f."""
    def E(w, b): return w * nbar(b * w)
    def S(w, b):
        z = b * w; n = nbar(z)
        return (n + 1) * mp.log(n + 1) - n * mp.log(n)
    Ei = E(wA, bA) + E(wB, bB); Si = S(wA, bA) + S(wB, bB)
    lo, hi = min(bA, bB), max(bA, bB)          # S is decreasing in beta; beta* lies between (run 2: bisection)
    for _ in range(300):
        mid = (lo + hi) / 2
        if S(wA, mid) + S(wB, mid) - Si > 0:
            lo = mid
        else:
            hi = mid
    bs = (lo + hi) / 2
    return Ei - (E(wA, bs) + E(wB, bs))

k, m = 2, 3
delta = mp.mpf('1e-3')
mbw = mp.mpf('1e-3')
W, pred, (u, v, wA, wB, bA, bB) = near_eq_case(None, k, m, delta, mbw / m)
Wr = W_rev(wA, wB, bA, bB)
check("O4 [numerics] classical regime, theta = 1/2: one k:m exchange captures the reversible work (W/W_rev within 2%)",
      abs(W / Wr - 1) < 0.02, f"W = {mp.nstr(W, 8)}, W_rev = {mp.nstr(Wr, 8)}, ratio {mp.nstr(W / Wr, 8)}")

ok5 = True; d5 = []
for dl in (Fr(1, 100), Fr(1, 1000)):
    p, q = simplest(Fr(1, 2), Fr(1, 2) * (1 + dl))
    theta = (Fr(p, q) - Fr(1, 2)) / (Fr(1, 2) * dl)
    bound = 4 * theta * (1 - theta) < 8 * dl
    # classical-regime ratio W_min / W_rev with beta w_A tiny
    beta = mp.mpf('1e-6')
    wA = mp.mpf(1); wB = mp.mpf(2)
    bA = beta * (1 + mp.mpf(dl.numerator) / dl.denominator); bB = beta
    u = mp.exp(-bA * wA); v = mp.exp(-bB * wB)
    Wm, _ = closed_form(u, v, wA, wB, p, q)
    Wr = W_rev(wA, wB, bA, bB)
    rat = Wm / Wr
    ok5 &= bound and rat < 8 * (mp.mpf(dl.numerator) / dl.denominator) * (1 + 10 * mp.mpf(dl.numerator) / dl.denominator)
    d5.append(f"delta={dl}: minimal {p}/{q}, 4theta(1-theta) = {float(4 * theta * (1 - theta)):.5f}, W_min/W_rev = {mp.nstr(rat, 6)}")
phi = (1 + mp.sqrt(5)) / 2
xg = 1 / phi
vals = []
for i in range(200):
    dl = mp.mpf(10) ** (-4 + 2 * mp.mpf(rng.random()))
    # simplest fraction inside (1/phi, (1+dl)/phi) via convergent search with exact-ish predicates at 40 digits
    lo, hi = xg, xg * (1 + dl)
    lp, lq, rp, rq = 0, 1, 1, 0
    while True:
        a_, b_ = lp + rp, lq + rq
        f = mp.mpf(a_) / b_
        if f <= lo:
            lp, lq = a_, b_
        elif f >= hi:
            rp, rq = a_, b_
        else:
            break
    theta = (mp.mpf(a_) / b_ - lo) / (hi - lo)
    vals.append(4 * theta * (1 - theta))
mg = mp.fsum(vals) / len(vals)
ok5 &= mg > mp.mpf('0.3')
d5.append(f"golden: mean 4theta(1-theta) = {mp.nstr(mg, 5)} over 200 log-uniform delta")
check("O5 resonance penalty in the prize: x=1/2 minimal exchange W_min/W_rev < 8 delta; golden mean 4theta(1-theta) > 0.3",
      ok5, "; ".join(d5))
print(f"\nTOTAL: {sum(res)}/{len(res)} PASS")
